// runOnceForEachItem
const j = $input.item.json;

// 1 — extract raw text from OpenAI v2.1 response
let rawText = '';
const t = j?.output?.[0]?.content?.[0]?.text;
if (typeof t === 'string' && t.trim()) rawText = t.trim();
else if (typeof j?.content === 'string' && j.content.trim()) rawText = j.content.trim();
if (!rawText) throw new Error('Empty OpenAI response. Keys: ' + Object.keys(j || {}).join(', '));

// 2 — extract JSON block
const s = rawText.indexOf('{');
const e = rawText.lastIndexOf('}');
if (s < 0 || e <= s) throw new Error('No JSON found. Snippet: ' + rawText.slice(0, 200));
let parsed;
try { parsed = JSON.parse(rawText.slice(s, e + 1)); }
catch(err) { throw new Error('JSON.parse failed: ' + err.message); }

// 3 — whitelist candidate fields
const candidate = {
  cv:            !!parsed.cv,
  full_name:     String(parsed.full_name     || ''),
  sex:           String(parsed.sex           || ''),
  birth_date:    parsed.birth_date           || null,
  contact_phone: parsed.contact_phone        || null,
  email:         String(parsed.email         || ''),
  country:       parsed.country              || null,
  city:          parsed.city                 || null,
  citizenship:   parsed.citizenship          || null,
  position:      String(parsed.position      || ''),
  employment:    parsed.employment           || null,
  experience:    parseInt(parsed.experience) || 0,
  skills:        Array.isArray(parsed.skills) ? parsed.skills.map(s => String(s)) : [],
  salary:        parsed.salary ? parseInt(parsed.salary) : null
};

// 4 — email metadata from Prepare PDF Text (cross-node ref, matches by item index)
const meta = $('Prepare PDF Text').item.json;
const emailFrom    = String(meta.emailFrom    || '');
const emailSubject = String(meta.emailSubject || '');
const messageId    = String(meta.messageId    || '');

return { json: JSON.parse(JSON.stringify({
  cv: candidate.cv, candidate, emailFrom, emailSubject, messageId
})) };

// runOnceForAllItems — items = all vacancy rows from Get Vacancies
// runs ONCE per candidate batch, not once per vacancy row
const parsed = $('Parse Candidate JSON').first().json;
const candidate  = parsed.candidate;
const emailFrom  = parsed.emailFrom;
const emailSubject = parsed.emailSubject;
const messageId  = parsed.messageId;

const vacancies = $input.all()
  .map((item, index) => ({
    row_number: index + 2,
    title:      item.json['Должность'] || item.json['title']       || '',
    description: [
      item.json['Описание']    || item.json['description']  || '',
      item.json['Требования']  || item.json['requirements'] || '',
      item.json['Зарплата']    ? 'Зарплата: ' + item.json['Зарплата'] : ''
    ].filter(Boolean).join('. ')
  }))
  .filter(v => v.title);

if (vacancies.length === 0) {
  throw new Error('No vacancies found in Google Sheets. Please fill the Vacancies sheet.');
}

const userContent = JSON.stringify({ candidate, vacancies });
return [{ json: { userContent, candidate, vacancies, emailFrom, emailSubject, messageId } }];

// runOnceForAllItems
const allItems = $input.all();
const results  = [];

for (const item of allItems) {
  const j = item.json;

  // 1 — extract raw text from OpenAI v2.1 response
  let rawText = '';
  const t = j?.output?.[0]?.content?.[0]?.text;
  if (typeof t === 'string' && t.trim()) rawText = t.trim();
  else if (typeof j?.content === 'string' && j.content.trim()) rawText = j.content.trim();
  if (!rawText) throw new Error('Empty OpenAI response. Input keys: ' + Object.keys(j || {}).join(', '));

  // 2 — extract JSON block
  const s = rawText.indexOf('{');
  const e = rawText.lastIndexOf('}');
  if (s < 0 || e <= s) throw new Error('No JSON object found. Text snippet: ' + rawText.slice(0, 200));
  let parsed;
  try { parsed = JSON.parse(rawText.slice(s, e + 1)); }
  catch(err) { throw new Error('JSON.parse failed: ' + err.message + ' | snippet: ' + rawText.slice(s, s + 200)); }

  // 3 — build candidateSummary
  const sum = parsed.candidate_summary || {};
  const candidateSummary = {
    full_name:                        String(sum.full_name || ''),
    position_raw:                     String(sum.position_raw || ''),
    position_family:                  String(sum.position_family || ''),
    normalized_skills:                Array.isArray(sum.normalized_skills) ? sum.normalized_skills.map(String) : [],
    experience_years:                 parseInt(sum.experience_years) || 0,
    seniority:                        String(sum.seniority || ''),
    employment:                       String(sum.employment || ''),
    city:                             String(sum.city || ''),
    country:                          String(sum.country || ''),
    salary_expectation_rub_per_month: parseInt(sum.salary_expectation_rub_per_month) || 0,
    contacts:                         String(sum.contacts || '')
  };

  const cleanMatch = m => ({
    row_number: parseInt(m.row_number) || 0,
    title:      String(m.title  || ''),
    family:     String(m.family || ''),
    score:      parseInt(m.score) || 0,
    reasons:    Array.isArray(m.reasons) ? m.reasons.map(String) : [],
    risks:      Array.isArray(m.risks)   ? m.risks.map(String)   : []
  });

  const qualifiedMatches = (parsed.matches    || []).map(cleanMatch).filter(m => m.score >= 60);
  const nearMisses       = (parsed.near_misses || []).map(cleanMatch);

  const prev      = $('Prepare Matching').first().json;
  const candidate = (prev && prev.candidate) ? JSON.parse(JSON.stringify(prev.candidate)) : {};
  const emailFrom = String((prev && prev.emailFrom) || '');
  const messageId = String((prev && prev.messageId) || '');

  // 4 — flat output matching sheet columns exactly
  results.push({ json: JSON.parse(JSON.stringify({
    hasMatch:            qualifiedMatches.length >= 1,
    cv:                  candidate.cv ?? false,
    full_name:           candidate.full_name    || candidateSummary.full_name || '',
    sex:                 candidate.sex          || '',
    birth_date:          candidate.birth_date   || '',
    email:               candidate.email        || '',
    phone:               candidate.contact_phone || '',
    city:                candidate.city         || candidateSummary.city    || '',
    country:             candidate.country      || candidateSummary.country || '',
    citizenship:         candidate.citizenship  || '',
    position:            candidate.position     || candidateSummary.position_raw || '',
    experience_years:    candidateSummary.experience_years || candidate.experience || 0,
    employment:          candidate.employment   || candidateSummary.employment || '',
    skills:              Array.isArray(candidate.skills) ? candidate.skills.join(', ') : '',
    salary_expectation:  candidateSummary.salary_expectation_rub_per_month || candidate.salary || 0,
    matched_vacancies:   qualifiedMatches.map(m => m.title).join(', '),
    match_reasons:       qualifiedMatches.map(m => m.title + ': ' + m.reasons.join('; ')).join(' | '),
    near_miss_vacancies: nearMisses.map(m => m.title).join(', '),
    rejection_reasons:   nearMisses.map(m => m.title + ': ' + m.risks.join('; ')).join(' | '),
    email_from:          emailFrom,
    message_id:          messageId,
    emailFrom:           emailFrom,
    messageId:           messageId,
    matches:             JSON.stringify(qualifiedMatches),
    nearMisses:          JSON.stringify(nearMisses),
    candidateSummary:    JSON.stringify(candidateSummary),
    candidate:           JSON.stringify(candidate)
  })) });
}

return results;

// runOnceForEachItem — tag PDF key, pass binary through (no copy/rename)
const j = $input.item.json;
const binary = $input.item.binary ?? {};

// Find first PDF key using only metadata (never touch binary data itself)
const pdfKey = Object.keys(binary).find(k =>
  k.startsWith('attachment') && (
    (binary[k].mimeType ?? '').includes('pdf') ||
    (binary[k].fileName ?? '').toLowerCase().endsWith('.pdf')
  )
) ?? null;

return {
  json: {
    hasPDF: !!pdfKey,
    pdfBinaryKey: pdfKey ?? '',
    fileName: pdfKey ? (binary[pdfKey].fileName ?? pdfKey) : '',
    emailId: j.id ?? '',
    threadId: j.threadId ?? '',
    emailFrom: j.from?.value?.[0]?.address ?? '',
    emailFromName: j.from?.value?.[0]?.name ?? '',
    subject: j.subject ?? '',
    messageId: j.messageId ?? '',
    emailText: j.text ?? ''
  },
  binary: $input.item.binary
};

